$q_citas = $pdo->prepare("SELECT COUNT(*) FROM citas WHERE id_cliente=? AND estado='Programada' AND fecha >= CURDATE()"); $q_citas->execute([$id_cliente]);
$metricas = [$contar("estado NOT IN ('Terminada','Cancelada','Rechazada')"), (int) $q_metricas->fetchColumn(), (int) $q_citas->fetchColumn()];
$q = $pdo->prepare('SELECT s.*, c.id_cotizacion, c.costo_total, c.estado AS estado_cotizacion FROM solicitudes s LEFT JOIN cotizaciones c ON c.id_solicitud=s.id_solicitud WHERE s.id_cliente=? ORDER BY s.fecha_solicitud DESC'); $q->execute([$id_cliente]); $solicitudes = $q->fetchAll();
